#!/usr/bin/env bash
# ═══════════════════════════════════════════════════════════════════════════════
#  gocode v2.0.0 — Self-Extracting Installer
#  Run: bash setup_v2.sh
#  Requirements: git, go 1.22+
# ═══════════════════════════════════════════════════════════════════════════════
set -euo pipefail

GOCODE_DIR="$HOME/.gocode"
SRC_DIR="$HOME/gocode-go"
BINARY="$GOCODE_DIR/gocode"
VERSION="2.0.0"

C_CYAN='\033[0;96m'
C_GREEN='\033[0;92m'
C_YELLOW='\033[0;93m'
C_RED='\033[0;91m'
C_DIM='\033[2m'
C_BOLD='\033[1m'
C_RESET='\033[0m'

info()  { echo -e "${C_CYAN}[INFO]${C_RESET}  $1"; }
ok()    { echo -e "${C_GREEN}[OK]  ${C_RESET}  $1"; }
warn()  { echo -e "${C_YELLOW}[WARN]${C_RESET}  $1"; }
err()   { echo -e "${C_RED}[ERR] ${C_RESET}  $1"; exit 1; }
step()  { echo -e "\n${C_BOLD}${C_CYAN}──${C_RESET} ${C_BOLD}$1${C_RESET}"; }
banner() {
  echo ""
  echo -e "${C_CYAN}${C_BOLD}  ██████╗  ██████╗  ██████╗ ██████╗ ██████╗ ███████╗${C_RESET}"
  echo -e "${C_CYAN}${C_BOLD}  ██╔════╝ ██╔═══██╗██╔════╝██╔═══██╗██╔══██╗██╔════╝${C_RESET}"
  echo -e "${C_CYAN}${C_BOLD}  ██║  ███╗██║   ██║██║     ██║   ██║██║  ██║█████╗  ${C_RESET}"
  echo -e "${C_CYAN}${C_BOLD}  ██║   ██║██║   ██║██║     ██║   ██║██║  ██║██╔══╝  ${C_RESET}"
  echo -e "${C_CYAN}${C_BOLD}  ╚██████╔╝╚██████╔╝╚██████╗╚██████╔╝██████╔╝███████╗${C_RESET}"
  echo -e "${C_CYAN}${C_BOLD}  ╚═════╝  ╚═════╝  ╚═════╝ ╚═════╝ ╚═════╝ ╚══════╝${C_RESET}"
  echo -e "  ${C_DIM}installer v${VERSION} · github.com/acemaster-gh/gocode${C_RESET}"
  echo ""
}

banner

# ── Checks ─────────────────────────────────────────────────────────────────────
step "Checking requirements"

command -v go &>/dev/null  || err "Go not found. Install from https://go.dev/dl/"
command -v git &>/dev/null || err "git not found."

GO_VER=$(go version | awk '{print $3}' | sed 's/go//')
MAJOR=$(echo "$GO_VER" | cut -d. -f1)
MINOR=$(echo "$GO_VER" | cut -d. -f2)
if [[ $MAJOR -lt 1 || ( $MAJOR -eq 1 && $MINOR -lt 22 ) ]]; then
  err "Go 1.22+ required (found: $GO_VER). Upgrade from https://go.dev/dl/"
fi
ok "Go $GO_VER"

# ── Extract source ─────────────────────────────────────────────────────────────
step "Extracting source"

mkdir -p "$HOME"
TMP_TAR=$(mktemp /tmp/gocode-XXXXXX.tar.gz)
trap 'rm -f "$TMP_TAR"' EXIT

echo "" | base64 -d > "$TMP_TAR"

if [[ -d "$SRC_DIR" ]]; then
  warn "Source dir exists: $SRC_DIR"
  read -rp "  Overwrite? [y/N]: " CONFIRM
  [[ "${CONFIRM,,}" == "y" ]] || { echo "Cancelled."; exit 0; }
  rm -rf "$SRC_DIR"
fi

tar xzf "$TMP_TAR" -C "$HOME"
ok "Source extracted → $SRC_DIR"

# ── Create ~/.gocode dirs ──────────────────────────────────────────────────────
step "Creating directories"
mkdir -p "$GOCODE_DIR"/{data,plugins,backups}
ok "$GOCODE_DIR"

# ── Dependencies ───────────────────────────────────────────────────────────────
step "Fetching Go modules"
cd "$SRC_DIR"
go mod tidy
ok "Dependencies resolved"

# ── Build ──────────────────────────────────────────────────────────────────────
step "Building binary"
go build -ldflags "-X main.Version=${VERSION} -s -w" -o "$BINARY" .
chmod +x "$BINARY"
ok "Built → $BINARY"

# ── PATH setup ─────────────────────────────────────────────────────────────────
step "PATH configuration"
SHELL_RC=""
case "$SHELL" in
  */zsh)  SHELL_RC="$HOME/.zshrc" ;;
  */fish) SHELL_RC="$HOME/.config/fish/config.fish" ;;
  *)      SHELL_RC="$HOME/.bashrc" ;;
esac

PATH_LINE='export PATH="$HOME/.gocode:$PATH"'
if [[ -f "$SHELL_RC" ]] && grep -q '\.gocode' "$SHELL_RC" 2>/dev/null; then
  ok "PATH already configured in $SHELL_RC"
else
  echo "" >> "$SHELL_RC"
  echo "# gocode v2" >> "$SHELL_RC"
  echo "$PATH_LINE" >> "$SHELL_RC"
  ok "Added to $SHELL_RC"
fi

# Also export for this session
export PATH="$GOCODE_DIR:$PATH"

# ── Migrate v1 data ────────────────────────────────────────────────────────────
step "Checking for v1 data migration"
V1_REGISTRY="$HOME/.devsession/projects.json"
if [[ -f "$V1_REGISTRY" ]]; then
  cp "$V1_REGISTRY" "$GOCODE_DIR/data/projects.json"
  ok "Migrated v1 registry → $GOCODE_DIR/data/projects.json"
else
  info "No v1 data found — fresh install."
fi

# ── Done ────────────────────────────────────────────────────────────────────────
echo ""
echo -e "  ${C_GREEN}${C_BOLD}✓ gocode v${VERSION} installed!${C_RESET}"
echo ""
echo -e "  ${C_DIM}Binary:  $BINARY${C_RESET}"
echo -e "  ${C_DIM}Source:  $SRC_DIR${C_RESET}"
echo -e "  ${C_DIM}Data:    $GOCODE_DIR${C_RESET}"
echo ""
echo -e "  ${C_BOLD}Next steps:${C_RESET}"
echo -e "  ${C_CYAN}1.${C_RESET}  Reload shell:   ${C_DIM}source $SHELL_RC${C_RESET}"
echo -e "  ${C_CYAN}2.${C_RESET}  Configure:      ${C_DIM}gocode config${C_RESET}"
echo -e "  ${C_CYAN}3.${C_RESET}  Create project: ${C_DIM}gocode new${C_RESET}"
echo ""
